import ast, base64, hashlib, json, pathlib, types
data=json.loads(base64.b64decode(''))
checks=[]
for name,source in data.items():
    tree=ast.parse(source)
    compile(tree,'<'+name+'>','exec')
    checks.append({'name':name+':whole_ast_compile_only','passed':True,'bytes':len(source.encode()),'sha256':hashlib.sha256(source.encode()).hexdigest()})
tree=ast.parse(data['launcher'])
guards=[x for x in tree.body if isinstance(x,ast.Assert) and '__file__' in ast.unparse(x.test)]
assert len(guards)==1
selected=compile(ast.Module(body=guards,type_ignores=[]),'<actual-entry-guard>','exec')
root=pathlib.Path('/home/qian-qi/heptabao-cold-h2-normal-20261105-r1/control-r3')
def BoundPath(value):
    return types.SimpleNamespace(resolve=lambda strict:pathlib.Path(value))
exec(selected,{'Path':BoundPath,'__file__':str(root/'launch_normal_cold_h2.py'),'REVISION_CONTROL':root})
checks.append({'name':'actual_entry_guard_accepts_exact_new_control_path','passed':True})
for value in ('/home/qian-qi/heptabao-cold-h2-normal-20261105-r1/control/launch_normal_cold_h2.py',str(root/'other.py')):
    rejected=False
    try:exec(selected,{'Path':BoundPath,'__file__':value,'REVISION_CONTROL':root})
    except AssertionError:rejected=True
    assert rejected
checks.append({'name':'actual_entry_guard_rejects_old_control_and_wrong_basename','passed':True})
carrier=ast.parse(data['carrier'])
imports={a.name for n in carrier.body if isinstance(n,ast.Import) for a in n.names}
assert imports=={'base64','hashlib','json','os','stat','sys','time'}
assert not any(isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id in ('exec','eval') for n in ast.walk(carrier))
checks.append({'name':'carrier_no_dynamic_source_execution_or_process_module','passed':True})
print(json.dumps({'schema':'heptabao.fresh-control-ast-and-entry-contract.v1','checks':checks,'count':len(checks),'module_executed':False,'selected_assertion_only':True,'files_opened':0,'children':0,'remote_calls':0},sort_keys=True))
